SELECT CASE WHEN d.budget >= 4117000 THEN 'high' WHEN d.budget >= 2026000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN e.level = 'L4' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l4, SORT_ARRAY(COLLECT_SET(e.job_title)) AS job_title_list FROM employees e INNER JOIN departments d ON d.id = e.dept_id WHERE d.budget >= 3732000 GROUP BY CASE WHEN d.budget >= 4117000 THEN 'high' WHEN d.budget >= 2026000 THEN 'mid' ELSE 'low' END;
